from datetime import datetime
from pathlib import Path
import tempfile
import unittest
from unittest.mock import patch

import api_server
import categories
import config
import database
import uniclubs_database


class PublicApiTests(unittest.TestCase):
    """Build disposable source files and replace only the remote-refresh boundary."""

    def setUp(self):
        """Create a validated public sport seed and UTC club dates around a DST transition."""
        temporary = tempfile.TemporaryDirectory(prefix='weekwise-public-api-test-')
        self.addCleanup(temporary.cleanup)
        self.directory = Path(temporary.name)
        self.sport_path = self.directory / 'sport.sqlite'
        self.clubs_path = self.directory / 'clubs.sqlite'
        self.make_sport()
        self.make_clubs()
        self.freshness = {'available': True, 'source_success_utc': '2026-11-21T12:00:00Z',
                          'refresh_ok': True, 'stale': False,
                          'checked_at_utc': '2026-11-21T12:01:00Z', 'changed': False}
        refresh = patch('api_server.public_api_data.ensure_uniclubs',
                        return_value=self.freshness)
        self.refresh = refresh.start()
        self.addCleanup(refresh.stop)
        self.application = api_server.create_public_app(
            self.sport_path, self.clubs_path, refresh=False)
        self.application.testing = True
        self.client = self.application.test_client()

    def make_sport(self):
        """Use the real app schema with synthetic public rows and explicit projection evidence."""
        connection = database.get_connection(self.sport_path)
        try:
            database.init_db(connection)
            categories.seed_categories(connection, categories.load_taxonomy())
            bundle = connection.execute('SELECT id FROM bundles WHERE key=?',
                                        ('sports_racket',)).fetchone()[0]
            with connection:
                connection.execute('''INSERT INTO series
                    (id,source,external_id,title,description,organizer,bundle_id,sport,
                     location_type,source_url,is_recurring)
                    VALUES (17,'unisport','history-pattern:1','Synthetic tennis',
                            ?,'Unisport HSG',?,'Synthetic tennis','tba',?,1)''',
                    (config.TRAINING_CATALOGUE_DESCRIPTION, bundle,
                     config.UNISPORT_PUBLIC_SCHEDULE_URL))
                connection.execute('''INSERT INTO events
                    (id,series_id,start_time,end_time,end_is_estimated,status)
                    VALUES (71,17,'2026-11-16 07:00:00','2026-11-16 08:30:00',1,'unknown'),
                           (72,17,'2026-11-23 07:00:00','2026-11-23 08:30:00',1,'unknown')''')
                connection.execute('''INSERT INTO event_provenance
                    (event_id,kind,forecast_anchor_date,evidence_weeks,created_at)
                    VALUES (71,'projected','2026-11-06',3,'2026-11-15 09:00:00'),
                           (72,'projected','2026-11-06',3,'2026-11-15 09:00:00')''')
                settings = (('catalogue_id', 'reviewed-public-api-test'),
                            ('catalogue_mode', config.REVIEWED_CATALOGUE_MODE),
                            ('setup_done', '1'))
                connection.executemany('INSERT INTO app_settings (key,value) VALUES (?,?)',
                                       settings)
        finally:
            connection.close()

    def make_clubs(self):
        """Place exact local-midnight boundaries into the source's canonical UTC columns."""
        connection = uniclubs_database.get_connection(self.clubs_path)
        try:
            uniclubs_database.init_db(connection)
            with connection:
                connection.execute('''INSERT INTO clubs (id,external_id,name,source_url)
                    VALUES (7,'synthetic-club','Synthetic Club',?)''',
                    ('https://uniclubs.ch/hsg/clubs/synthetic',))
                starts = ('2027-03-27T22:59:59.000000Z', '2027-03-27T23:00:00.000000Z',
                          '2027-03-28T21:59:59.000000Z', '2027-03-28T22:00:00.000000Z')
                for event_id, start in enumerate(starts, 11):
                    connection.execute('''INSERT INTO events
                        (id,external_id,club_id,title,start_utc,end_utc,location,event_type,
                         source_url,publication_status,availability_state,requires_membership,
                         first_seen_utc,last_seen_utc,source_missing)
                        VALUES (?,?,7,'Synthetic workshop',?,NULL,'SQUARE','workshop',
                                ?,'published','open',NULL,?,?,0)''',
                        (event_id, 'synthetic-event-' + str(event_id), start,
                         'https://uniclubs.ch/hsg/clubs/synthetic/events/workshop',
                         '2026-11-20T12:00:00.000000Z', '2026-11-21T12:00:00.000000Z'))
                connection.execute('ALTER TABLE events ADD COLUMN private_note TEXT')
                connection.execute('UPDATE events SET private_note=?', ('private-marker',))
                connection.execute('CREATE TABLE private_profiles (private_name TEXT)')
                connection.execute('INSERT INTO private_profiles VALUES (?)', ('Private Name',))
        finally:
            connection.close()

    def test_sport_collection_uses_sql_date_range_and_preserves_evidence(self):
        """The requested half-open week returns one source row and its projection metadata."""
        response = self.client.get('/unisport/events',
                                   query_string={'from': '2026-11-16', 'to': '2026-11-23'})
        self.assertEqual(response.status_code, 200)
        self.assertEqual([row['id'] for row in response.json], [71])
        self.assertEqual(response.json[0]['provenance_kind'], 'projected')
        self.assertEqual(response.json[0]['status'], 'unknown')
        self.assertIsNone(response.json[0]['price_rappen'])

    def test_club_dates_are_zurich_dates_across_spring_dst(self):
        """A 23-hour Zurich day includes both exact source boundaries without UTC-date drift."""
        response = self.client.get('/uniclubs/events',
                                   query_string={'from': '2027-03-28', 'to': '2027-03-29'})
        self.assertEqual(response.status_code, 200)
        self.assertEqual([row['id'] for row in response.json], [12, 13])
        self.assertEqual(response.json[0]['start_utc'], '2027-03-27T23:00:00.000000Z')
        self.assertIsNone(response.json[0]['end_utc'])
        self.assertIsNone(response.json[0]['requires_membership'])
        self.assertEqual(response.json[0]['club_name'], 'Synthetic Club')

    def test_public_club_whitelist_excludes_extra_columns_and_tables(self):
        """Public responses cannot expose private data added to a local cache schema."""
        for path in ('/uniclubs/events/12', '/uniclubs/clubs', '/sources', '/health'):
            response = self.client.get(path)
            self.assertEqual(response.status_code, 200, path)
            text = response.get_data(as_text=True)
            self.assertNotIn('private_note', text)
            self.assertNotIn('private-marker', text)
            self.assertNotIn('Private Name', text)
            self.assertNotIn(str(self.directory), text)

    def test_unknown_ids_and_unpublished_paths_return_json_404(self):
        """Missing source IDs and private application routes remain absent from the public API."""
        for path in ('/unisport/events/999', '/uniclubs/events/999', '/users', '/favorites',
                     '/training_history', '/interactions'):
            response = self.client.get(path)
            self.assertEqual(response.status_code, 404, path)
            self.assertIn('error', response.json)

    def test_only_reading_methods_are_available(self):
        """A caller cannot create interactions or change a public occurrence through HTTP."""
        self.assertEqual(self.client.post('/interactions', json={}).status_code, 404)
        for path in ('/unisport/events', '/uniclubs/events', '/uniclubs/clubs'):
            self.assertEqual(self.client.post(path, json={}).status_code, 405)

    def test_out_of_range_ids_return_404_without_sqlite_integer_overflow(self):
        """Unbounded URI integers are invalid IDs, rather than internal storage failures."""
        for source in ('unisport', 'uniclubs'):
            response = self.client.get('/' + source + '/events/' + str(2 ** 100))
            self.assertEqual(response.status_code, 404)

    def test_bad_and_unbounded_date_queries_return_400(self):
        """Validate both collections before using attacker-controlled values in SQL."""
        invalid = ({}, {'from': '2026-11-16', 'to': '2026-11-16'},
                   {'from': '2026-11-23', 'to': '2026-11-16'},
                   {'from': '2026-11-16', 'to': '2027-11-16'},
                   {'from': '2026-11-16 OR 1=1', 'to': '2026-11-23'},
                   {'from': '2026-1-1', 'to': '2026-01-02'})
        for path in ('/unisport/events', '/uniclubs/events'):
            for query in invalid:
                with self.subTest(path=path, query=query):
                    self.assertEqual(self.client.get(path, query_string=query).status_code, 400)

    def test_requests_do_not_modify_source_databases(self):
        """The public endpoints open files read-only and preserve every existing source byte."""
        before = (self.sport_path.read_bytes(), self.clubs_path.read_bytes())
        for path in ('/', '/health', '/sources', '/unisport/events/71',
                     '/uniclubs/events/12', '/uniclubs/clubs'):
            self.assertEqual(self.client.get(path).status_code, 200)
        self.assertEqual((self.sport_path.read_bytes(), self.clubs_path.read_bytes()), before)

    def test_missing_club_storage_returns_sanitized_503(self):
        """A cache removed after startup must not create a new file or disclose its path."""
        self.clubs_path.unlink()
        response = self.client.get('/uniclubs/events/12')
        self.assertEqual(response.status_code, 503)
        self.assertFalse(self.clubs_path.exists())
        self.assertNotIn(str(self.directory), response.get_data(as_text=True))

    def test_public_factory_rejects_sport_database_containing_profile(self):
        """Accidentally pointing the public service at a private runtime must fail startup."""
        connection = database.get_connection(self.sport_path)
        try:
            database.create_user(connection, 'Private Name', now=datetime(2026, 11, 21))
        finally:
            connection.close()
        with self.assertRaises(ValueError):
            api_server.create_public_app(self.sport_path, self.clubs_path, refresh=False)

    def test_cached_clubs_remain_available_after_refresh_failure(self):
        """A failed source check leaves readable saved events and exposes stale metadata."""
        self.freshness.update(refresh_ok=False, stale=True)
        response = self.client.get('/uniclubs/events/12')
        self.assertEqual(response.status_code, 200)
        self.assertEqual(response.json['id'], 12)
        health = self.client.get('/health')
        self.assertEqual(health.status_code, 200)
        self.assertTrue(health.json['sources']['uniclubs']['refresh']['stale'])
        self.assertFalse(health.json['sources']['uniclubs']['refresh']['refresh_ok'])


if __name__ == '__main__':
    unittest.main()
